const P={};
/* ---------- SUN (SDO-style, pixelised) with calligraphic script L ---------- */
const SUNR=['#2a0402','#5e0c03','#9a1c06','#d23a0c','#f2641a','#fc9a2e','#ffd070','#fff4d0','#ffffff'];
const GLOW=['#1a0201','#4a0803','#8a1606','#c42a0a'];
